sys_ux_client_script.required_translations:
[
    {
        "message": "Supporting data is successfully saved for the record. Reload the form to add the basic criteria."
    },
    {
        "message": "Supporting data is successfully saved for the record."
    },
    {
        "message": "Supporting data could not be saved for the record."
    }
]

sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    if (event.payload.data.output.sysId) {
        if (api.data.get_existing_supporting_data.output.type == 'basic') {
            helpers.translate('Supporting data is successfully saved for the record. Reload the form to add the basic criteria.').then((value) => {
                api.emit("RECORD_PAGE_TABS#ADD_NOTIFICATIONS", {
                    items: [{
                        id: "alert1",
                        status: "info",
                        icon: "info-circle-outline",
                        content: value,
                        action: {
                            type: "dismiss"
                        }
                    }]
                });
                helpers.modal.close();
            });
        } else {
            helpers.translate('Supporting data is successfully saved for the record.').then((value) => {
                api.emit("RECORD_PAGE_TABS#ADD_NOTIFICATIONS", {
                    items: [{
                        id: "alert1",
                        status: "info",
                        icon: "info-circle-outline",
                        content: value,
                        action: {
                            type: "dismiss"
                        }
                    }]
                });
                helpers.modal.close();
            });
        }
    } else {
        helpers.translate('Supporting data could not be saved for the record.').then((value) => {
            api.emit("RECORD_PAGE_TABS#ADD_NOTIFICATIONS", {
                items: [{
                    id: "alert1",
                    status: "info",
                    icon: "info-circle-outline",
                    content: value,
                    action: {
                        type: "dismiss"
                    }
                }]
            });
            helpers.modal.close();
        });
    }
}
